    """Find the minimal edit from s_in to s_out."""
    # Simple implementation to find first differing character
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            return (c_in, c_out, i)

    # If one string is longer, handle that case
    if len(s_in) > len(s_out):
        return (s_in[len(s_out)], '', len(s_out))
    elif len(s_out) > len(s_in):
        return ('', s_out[len(s_in)], len(s_in))

    return ('', '', -1)

