    # Return specific candidates from most to least specific
    candidates = []

    # Most specific: exact character replacement
    if old_sub and new_sub:
        candidates.append((old_sub, new_sub))

    # General cases
    if old_sub and not new_sub:
        candidates.append((old_sub, ''))  # deletion

    return candidates

